CREATE TABLE ETL_PROCESS.T_LEGACY_CUSTOMER_ORDER_LINE_2 (
	WSHOP_CD VARCHAR(5) COMMENT 'The unique code for the Lidl webshop, where an order can be placed by a customer. The webshop is defined per political country.',
	CUST_ORDER_CREATE_TMSP TIMESTAMP_TZ(9) COMMENT 'The date when order was created in source system ( is used in reporting)',
	CUST_ORDER_DT DATE COMMENT 'The date when order was made',
	PROD_VARIANT_NR VARCHAR(20) COMMENT 'The product variant number',
	PROD_NR VARCHAR(20) COMMENT 'The number for internal onlineshop product, which is country_2 independent',
	CUST_NR VARCHAR(20) COMMENT 'A customer number from original system',	
	CUST_ORDER_NR VARCHAR(20) NOT NULL COMMENT 'The order number of the source system',
	CUST_ORDER_POS_NR NUMBER(38,0) NOT NULL COMMENT 'The particular position number of an item_2 in an order',
	PROD_QTY NUMBER(38,5) COMMENT 'Quantity of a particular product ordered',
	IS_BUNDLE_HEADER_FG BOOLEAN COMMENT 'Indicates if position represents a bundle header ( null in all the other cases)',
	BUNDLE_HEADER_POS_NR NUMBER(38,0) COMMENT 'In case of a line being a composition part of the bundle-header (see bundle header code field), it can be allocated with this field to its header item_2',
	CURR_CD VARCHAR(5) COMMENT 'Currency code in which order has been payed',	
	PROD_PRICE_NET_LOCAL_VAL NUMBER(38,5) COMMENT 'Original (listed) net price of a product in local currency',
	PROD_PRICE_GROSS_LOCAL_VAL NUMBER(38,5) COMMENT 'Original (listed) gross price of a product in local currency',
	PROD_PRICE_VAT_LOCAL_VAL NUMBER(38,5) COMMENT 'Original (listed) vat value on price of a product in local currency',	
	PROD_COUPON_NET_LOCAL_VAL NUMBER(38,5) COMMENT 'The net discount value for the (original/listed) product in local currency',
	PROD_COUPON_GROSS_LOCAL_VAL NUMBER(38,5) COMMENT 'The gross discount value for the (original/listed) product in local currency',
	PROD_COUPON_VAT_LOCAL_VAL NUMBER(38,5) COMMENT 'The discount vat value for the (original/listed) product in local currency',	
	DELIVERY_COST_NET_LOCAL_VAL NUMBER(38,5) COMMENT 'Article specific net delivery cost in local currency. This cost is optional and mostly article dependent. An example is a fridge which has additional delivery costs',
	DELIVERY_COST_GROSS_LOCAL_VAL NUMBER(38,5) COMMENT 'Article specific gross delivery cost in local currency. This cost is optional and mostly article dependent. An example is a fridge which has additional delivery costs.',
	DELIVERY_COST_VAT_LOCAL_VAL NUMBER(38,5) COMMENT 'Article specific delivery vat value in local currency. This tax value is optional and mostly article dependent. An example is a fridge which has additional delivery costs for which taxes might have to be paid',	
	DELIVERY_COUPON_NET_LOCAL_VAL NUMBER(38,5) COMMENT 'The net discount value for article specific delivery costs in local currency.',
	DELIVERY_COUPON_GROSS_LOCAL_VAL NUMBER(38,5) COMMENT 'The gross discount value for article specific delivery costs in local currency.',
	DELIVERY_COUPON_VAT_LOCAL_VAL NUMBER(38,5) COMMENT 'The discount vat value for article specific delivery costs in local currency',	
	DELIVERY_PAUSHAL_NET_LOCAL_VAL NUMBER(38,5) COMMENT 'A paushal for delivery costs splitted per every order position in netto and local currency',
	DELIVERY_PAUSHAL_GROSS_LOCAL_VAL NUMBER(38,5) COMMENT 'A paushal for delivery costs splitted per every order position in gross and local currency',
	DELIVERY_PAUSHAL_VAT_LOCAL_VAL NUMBER(38,5) COMMENT 'The vat value of the paushal delivery costs splitted per every order position in local currency',	
	DELIVERY_PAUSHAL_COUPON_NET_LOCAL_VAL NUMBER(38,5) COMMENT 'A discount value netto for paushal delivery cost splitted per every order position in local currency',
	DELIVERY_PAUSHAL_COUPON_GROSS_LOCAL_VAL NUMBER(38,5) COMMENT 'A discount value gross for paushal delivery cost splitted per every order position in local currency',
	DELIVERY_PAUSHAL_COUPON_VAT_LOCAL_VAL NUMBER(38,5) COMMENT 'A discount vat value for paushal delivery cost splitted per every order position in local currency',	
	IVP_PRICE_NET_LOCAL_VAL NUMBER(38,5) COMMENT 'Internal invoice price in local currency  netto',
	GLD_PRICE_NET_LOCAL_VAL NUMBER(38,5) COMMENT 'Moving average price in local currency netto',
	GLD_UNIT_PRICE_NET_EUR_VAL NUMBER(38,5) COMMENT 'The gld unit_2 price in sales_2 order line in euros for internal margin calculations',
	IVP_ORIGINAL_PRICE_NET_LOCAL_VAL NUMBER(38,5) COMMENT 'Internal invoice price in local currency  netto ( may be null and is used in calculation of ivp_price_net_local_val )',
	IVP_UNIT_PRICE_NET_EUR_VAL NUMBER(38,5) COMMENT 'This field is a derived one based on ivp_original_unit_price_net_eur_val and gld_unit_price_net_eur_val',
	IVP_ORIGINAL_UNIT_PRICE_NET_EUR_VAL NUMBER(38,5) COMMENT 'The ivp original unit_2 prices in sales_2 order line in euros for internal margin calculations',	
	COGS_PRICE_NET_LOCAL_VAL NUMBER(38,5) COMMENT 'Cost-of-Goods-sold, short: CoGs. Needed for calc of margin (= revenue - cogs )',	
	TAX_CLASS_CD VARCHAR(5) COMMENT 'The code identifying the tax class',
	DELIVERY_CUST_NR VARCHAR(20) COMMENT 'A customer number from original system',
	DELIVERY_ADDR_NR VARCHAR(100) COMMENT 'The address_2 number in source system',
	BILLING_ADDR_NR VARCHAR(100) COMMENT 'The address_2 number in source system',	
	IS_BLOCKED_DELIVERY_FG BOOLEAN COMMENT 'Flag which tells whether a delivery is being blocked currently. e.g. if customer orders with payment type \"Vorauskasse\" then the delivery will only start as soon as the money arrives',
	DELIVERY_BLOCKED_REASON_CD VARCHAR(5) COMMENT 'The code with the reason why the delivery is blocked for the specific customer order.',
	IS_ORDER_CANCEL_FG BOOLEAN COMMENT 'Flag telling whether the order has been cancelled by the customer or Lidl Digital',
	ORDER_CANCEL_STATUS_CD VARCHAR(5) COMMENT 'The code for the status_2 of cancellation',
	CUST_PAYM_METHOD_CD VARCHAR(5) COMMENT 'The code for the payment methods',
	SALES_CHANNEL_TYPE_CD VARCHAR(5) COMMENT 'The code for the device which was being used to order from the online webshop. Possible values are desktop browser, iOS or Android.',
	ORDER_CANCEL_REASON_CD VARCHAR(5) COMMENT 'The code for reason why the customer has cancelled or got been cancelled an order line/product',
	CUST_ORDER_TYPE_CD VARCHAR(5) COMMENT 'The differenciation whether the order will be fulfilled by Lidl (=intercompany) or a supplier_2 directly (= extracompnay)',
	CUST_ORDER_PERFORM_DT DATE COMMENT 'The timestamp when the delivery to the customer actually started. This timestamp is relevant from a financial perspective as until then you are not allowed to charge him/her. In case of serveral performance timestamps for a single article within a single order the last date is picked.',
	CUST_DELIVERY_TGT_DT DATE COMMENT 'The first date which has been communicated to the customer until when the shipment is meant to arrive',
	WH_CD VARCHAR(5) COMMENT 'The code for the warehouse from where particular product will be sent',
	PROD_ASSORTMENT_CLASS_CD VARCHAR(5) COMMENT 'The code for the indicating if product variant is a part of special offer or normal or special assortiment',
	SALES_SEGMENT_TYPE_CD VARCHAR(20) COMMENT 'The sales_2 channel name',
	ORDER_REASON_CD VARCHAR(5) COMMENT 'Order reason code on order document level ( 008 guter Service ,etc)',
	DELIVERY_SRC_TYPE_CD VARCHAR(5) COMMENT 'The code for source location_2 of product from where it is delivered i.e. from supplier_2 or warehouse directly',
	DROPSHIPMENT_ORDER_FG BOOLEAN COMMENT 'In case the material is being sent from the supplier_2 this field will be filled.',
	IS_PART_OF_BUNDLE_HEADER_CNT_FG BOOLEAN COMMENT 'Reporting relevant - if report uses the bundle header count use this flag. Set as ''true'' for bundle header and non-bundle item_2 and ''false'' for bundle position item_2 ',
	IS_PART_OF_BUNDLE_POS_CNT_FG BOOLEAN COMMENT 'Reporting relevant - if report uses the bundle header count use this flag. Set as ''true'' for bundle position and non-bundle item_2 and ''false'' for bundle header item_2 ',

	INITIAL_CUST_ORDER_NR VARCHAR(20) COMMENT 'The initial order number of the legacy source system (SEP)',
	IS_LEGACY_FG BOOLEAN COMMENT 'Technical field used to identify legacy data, for further use as a filter condition',
	WAS_NOT_MIGRATED_FG BOOLEAN COMMENT 'In case the order was not migrated to RJI during the 2021 SAP Migration',
	EXCHANGE_RATE NUMBER(9,5) COMMENT 'Currency exchange rate from our legacy systems (SEP, Qlikview)',

	DWH_CREATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
	DWH_UPDATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was last updated.',
	DWH_SRC_FILE_NAME VARCHAR(255) NOT NULL COMMENT 'The path and the name of the file(s) from which this record was loaded.',
	SRC_FILE_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was extracted from the source.',
	
	LEAD_SRC_LOG_SYS_CD VARCHAR(5) COMMENT 'SAP MANDT code associated with the source system',
	LEAD_SRC_NAME VARCHAR(100) COMMENT 'Source system from which the record was fetched (RJI or SEP)',
	
	CONSTRAINT PK_T_LEGACY_CUSTOMER_ORDER_LINE PRIMARY KEY (CUST_ORDER_NR, CUST_ORDER_POS_NR)
	
)COMMENT = 'Legacy data contains historical records with details of individual ordered items';